//! What the AL compiler reports for a language feature at each runtime: properties (per element kind, and per value),
//! data types, method attributes and object types (`catalog/alc-features.txt`, generated by
//! `tools/alc-runtimes/alc_features.py` with the corpus's AL compiler; al-runner issue 5573).
use crate::catalog::{AlcOutcome, AlcRuntime};
use al_version::Runtime;
use std::collections::HashMap;

/// The checked-in table, compiled into the binary (no file access at runtime, ADR-006).
const ALC_FEATURES: &str = include_str!("../catalog/alc-features.txt");

/// The kind of a feature: the first column of the table.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FeatureKind {
    /// A property, at an element kind (`page/layout/field`); `value` `*` or one value.
    Property,
    /// A data type, as a variable declares it.
    DataType,
    /// A method attribute.
    Attribute,
    /// An object type (`enum`, `reportextension`).
    Object,
}

impl FeatureKind {
    fn parse(s: &str) -> Option<FeatureKind> {
        Some(match s {
            "property" => FeatureKind::Property,
            "datatype" => FeatureKind::DataType,
            "attribute" => FeatureKind::Attribute,
            "object" => FeatureKind::Object,
            _ => return None,
        })
    }
}

type Key = (FeatureKind, String, String, String);

fn table() -> &'static HashMap<Key, AlcRuntime> {
    static TABLE: std::sync::OnceLock<HashMap<Key, AlcRuntime>> = std::sync::OnceLock::new();
    TABLE.get_or_init(|| parse(ALC_FEATURES).expect("catalog/alc-features.txt parses"))
}

/// Parses the table text: `<kind>\t<element kind>\t<name>\t<value>\t<runtimes>\t<other runtimes>` per row.
pub fn parse(text: &str) -> Result<HashMap<Key, AlcRuntime>, String> {
    let mut out = HashMap::new();
    for (n, l) in text.lines().enumerate() {
        if l.starts_with('#') || l.trim().is_empty() {
            continue;
        }
        let bad = |e: String| format!("alc-features.txt:{}: {e}", n + 1);
        let cols: Vec<&str> = l.splitn(6, '\t').collect();
        let [kind, ctx, name, value, ranges, rest] = cols[..] else {
            return Err(bad("expected six tab-separated columns".into()));
        };
        let kind = FeatureKind::parse(kind).ok_or_else(|| bad(format!("bad feature kind `{kind}`")))?;
        let entry = AlcRuntime::parse(ranges, rest).map_err(bad)?;
        out.insert(
            (kind, ctx.to_lowercase(), name.to_lowercase(), value.to_lowercase()),
            entry,
        );
    }
    Ok(out)
}

/// The row of a feature: for a property with a `value`, the row of that value if the table has one, else the row of
/// any value (`*`). `ctx` is the element kind of a property, `-` for the other kinds.
pub fn feature(kind: FeatureKind, ctx: &str, name: &str, value: Option<&str>) -> Option<&'static AlcRuntime> {
    let t = table();
    let (ctx, name) = (ctx.to_lowercase(), name.to_lowercase());
    if let Some(v) = value {
        if let Some(r) = t.get(&(kind, ctx.clone(), name.clone(), v.trim().to_lowercase())) {
            return Some(r);
        }
    }
    t.get(&(kind, ctx, name, "*".to_string()))
}

/// The AL0666 diagnostics alc reports for the feature at runtime `at`, as (the name alc quotes, the text after "The
/// supported runtime versions are: "); empty when the feature compiles there, when alc reports something else, or
/// when the table has no row.
pub fn al0666_at(row: &AlcRuntime, at: Runtime) -> Vec<(&str, &str)> {
    if row.compiles_at(at) != Some(false) {
        return Vec::new();
    }
    match row.outcome_at(at) {
        Some(AlcOutcome::Al0666(text)) => text
            .split(" && ")
            .filter_map(|one| {
                let rest = one.strip_prefix('\'')?;
                let (name, text) = rest.split_once("' ")?;
                Some((name, text))
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// The AL compiler version that measured the table (its first line names it).
pub fn compiler() -> &'static str {
    ALC_FEATURES
        .lines()
        .next()
        .and_then(|l| l.split("AL compiler ").nth(1))
        .and_then(|v| v.split(". ").next())
        .unwrap_or("unknown")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn r(s: &str) -> Runtime {
        Runtime::parse(s).unwrap()
    }

    #[test]
    fn a_feature_row_parses_with_the_names_alc_quotes() {
        let t = parse(
            "# header\nproperty\tpage/layout/area\tObsoleteState\t*\t4.0..13.0\t1.0..4.0 context; 13.0.. AL0666 'ObsoleteState' '4.0' until, but not including '13.0'\n\
             property\tpageextension/layout/modify:part\tEditable\t*\tnone\t1.0.. AL0666 'Modifying Editable from Extensions' '1.0' until, but not including '10.1'\n\
             property\tpage/layout/field\tImportance\tOptional\t1.0..3.0\t3.0.. AL0666 'Optional' '1.0' until, but not including '3.0' && 'Importance' 'x'\n",
        )
        .unwrap();
        let area = &t[&(
            FeatureKind::Property,
            "page/layout/area".into(),
            "obsoletestate".into(),
            "*".into(),
        )];
        assert_eq!(
            al0666_at(area, r("16.1")),
            vec![("ObsoleteState", "'4.0' until, but not including '13.0'")]
        );
        assert!(al0666_at(area, r("5.0")).is_empty());
        assert!(
            al0666_at(area, r("2.0")).is_empty(),
            "another line of the probe fails there"
        );
        let ed = &t[&(
            FeatureKind::Property,
            "pageextension/layout/modify:part".into(),
            "editable".into(),
            "*".into(),
        )];
        assert_eq!(
            al0666_at(ed, r("18.0")),
            vec![(
                "Modifying Editable from Extensions",
                "'1.0' until, but not including '10.1'"
            )]
        );
        let opt = &t[&(
            FeatureKind::Property,
            "page/layout/field".into(),
            "importance".into(),
            "optional".into(),
        )];
        assert_eq!(
            al0666_at(opt, r("18.0")),
            vec![
                ("Optional", "'1.0' until, but not including '3.0'"),
                ("Importance", "'x'")
            ]
        );
    }

    #[test]
    fn the_checked_in_table_parses_and_names_its_compiler() {
        assert!(!table().is_empty());
        assert!(compiler().starts_with("30."), "{}", compiler());
    }
}
